char **ft_split(char *s, char c);

static void put_str(char *s)
{
	int i;

	i = 0;
	while (s[i])
		i++;
	write(1, s, i);
}

int main(void)
{
	char **r;
	int i;

	r = ft_split("  a,bb,,ccc  ,d", ',');
	i = 0;
	while (r && r[i])
	{
		put_str(r[i]);
		write(1, "|", 1);
		i++;
	}
	write(1, "\n", 1);
	return (0);
}

